WITH gaps AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY device ORDER BY started_at, id) + INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM sessions), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN burst_id >= 8 THEN 'LARGE' ELSE 'SMALL' END AS burst_id_tier, DATE_TRUNC('QUARTER', started_at) AS quarter_start, DATE_TRUNC('MONTH', started_at) AS activity_month, COUNT(CASE WHEN browser = 'Safari' THEN 1 END) AS safari_count, COUNT(CASE WHEN country = 'SG' THEN 1 END) AS sg_count FROM islands GROUP BY CASE WHEN burst_id >= 8 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('QUARTER', started_at), DATE_TRUNC('MONTH', started_at);
